function getSplunkTranslation(key, lang) {
    if (splunkTranslations[lang] && splunkTranslations[lang][key]) {
        return splunkTranslations[lang][key];
    }
    if (splunkTranslations.en && splunkTranslations.en[key]) {
        return splunkTranslations.en[key];
    }
    return null;
}

function applySplunkTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.splunk.')) {
            const translation = getSplunkTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applySplunkTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applySplunkTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applySplunkTranslations(currentLang);
}


